/* Teaching revision: visible villus adaptations, named materials, tooth/gum scurvy. */
(() => {
'use strict';
const M=window.MechanismCore,V=window.VillusStudio,D=window.LearningDiagrams,P=window.DiagramPresentation;
const {txt,path,circle,token,at,ramp,lerp}=M,oldRender=window.learningSceneSVG,oldTeaching=window.processTeaching,oldSpec=P.spec;
window.FocusedLearning.tabs={overview:['Villus + cell','絨毛及細胞'],...window.FocusedLearning.tabs};
function overview(t){let o=txt(560,35,'One villus: see all three epithelial adaptations','一條絨毛：同時看見三項上皮適應',25);
 o+=D.villusUnit(300,665,390,180,t);
 // The single cell ribbon belongs to the outside of the villus, not its core.
 o+=path([[402,400],[470,400],[680,305]],'#9d8275',2,'stroke-dasharray="7 6"')+path([[402,430],[470,430],[680,620]],'#9d8275',2,'stroke-dasharray="7 6"');
 o+=txt(225,180,'Whole villus','整條絨毛',23)+txt(840,180,'ONE epithelial cell: enlarged','放大其中一個上皮細胞',23);
 o+=V.enterocyte(690,310,270,300,{brush:false});for(let j=0;j<15;j++){const x=695+j*18;o+=`<path data-overview-microvillus="${j}" d="M${x} 310 V260 Q${x+6} 247 ${x+12} 260 V310" fill="#f3d4c1" stroke="#ae7e72" stroke-width="2"/>`}
 for(const [i,p]of [[730,365],[800,355],[885,365],[745,425],[835,420],[910,435],[735,485],[900,490]].entries())o+=`<g data-overview-mitochondrion="${i}">${V.mitochondrion(...p,.8)}</g>`;
 o+=txt(565,305,'Microvilli','微絨毛',19)+path([[615,305],[704,270]],'#a27c6b',2)+txt(560,420,'Many mitochondria','大量線粒體',19)+path([[635,420],[730,425]],'#a27c6b',2);
 o+=txt(115,470,'ONE cell layer','只有一層細胞',20)+path([[180,475],[207,475]],'#a27c6b',2)+path([[199,462],[222,462],[222,488],[199,488]],'#3f8d78',3);
 o+=path([[690,660],[1000,660]],'#a86f83',34)+path([[690,660],[1000,660]],'#f0d8df',26)+txt(1000,710,'Capillary blood','微血管血液',19,'end');
 // ATP goes to a basolateral pump; glucose uses its own entry/exit sites.
 o+=path([[948,465],[971,465],[971,493],[948,493]],'#438e76',5)+txt(1030,450,'Na⁺ pump','鈉泵',17)+path([[952,620],[977,620]],'#438e76',9);
 for(let i=0;i<5;i++){const q=(t*.8+i/5)%1,p=at([[835,420],[900,450],[958,479]],q);o+=token(...p,'#cba62e',`data-overview-atp="${i}"`,7)}
 for(let i=0;i<5;i++){const x=780+i*25,q=ramp(t,.06+i*.035,.8+i*.03),p=at([[x,225],[x,260],[x,310],[825,365],[925,550],[965,610],[965,660],[720+i*40,660]],q);o+=path([[x-6,251],[x-6,273],[x+6,273],[x+6,251]],'#438e76',4)+token(...p,'glucose',`data-overview-glucose="${i}"`,9)}
 o+=txt(300,730,'Capillary network around central lacteal','微血管網圍繞中央乳糜管',19)+txt(825,743,'Microvilli add area · one layer shortens the route','微絨毛增加面積；單層縮短運輸路徑',19);
 return V.wrap(o,'Villus adaptations with enlarged epithelial cell');}
function bileState(t,bile){const split=bile?ramp(t,.1,.35):0,digested=Math.floor(ramp(t,.53,1)*(bile?8:4)+1e-8),remaining=1-digested/12,drops=[];
 if(split<1)drops.push({id:'large',p:[0,0],r:60*Math.cbrt((1-split)*remaining)});
 if(split>0)for(let i=0;i<8;i++){const a=i*Math.PI/4;drops.push({id:'small-'+i,p:[Math.cos(a)*100*split,Math.sin(a)*100*split],r:30*Math.cbrt(split*remaining)})}
 return {split,digested,remaining,drops};}
function enzymeGlyph(x,y,id,angle=0){return `<g data-lipase-identity="${id}" transform="rotate(${angle} ${x} ${y})"><path d="M${x+9} ${y-8} A12 12 0 1 0 ${x+9} ${y+8} L${x} ${y}Z" fill="#397fa8" stroke="#fff" stroke-width="1.5"/></g>`}
function bileLipasePanel(t,bile,x,cy,k){const s=bileState(t,bile);let o='';
 o+=txt(x,185,bile?'Lipase + bile salts':'Lipase alone',bile?'脂肪酶 + 膽鹽':'只有脂肪酶',23);
 o+=txt(x,247,t<.5?'Same initial fat volume':`Digested portions: ${s.digested} / 12`,t<.5?'最初脂肪量相同':`已消化的示意份數：${s.digested}／12`,19);
 for(const d of s.drops){o+=circle(x+d.p[0],cy+d.p[1],d.r,'#e5b56b',`data-emulsion-drop="${k}-${d.id}" stroke="#b47a32" stroke-width="3"`);if(bile)for(let j=0;j<5;j++){const a=j/5*Math.PI*2,rr=d.r,inside=[x+d.p[0]+Math.cos(a)*(rr-3),cy+d.p[1]+Math.sin(a)*(rr-3)],outside=[x+d.p[0]+Math.cos(a)*(rr+7),cy+d.p[1]+Math.sin(a)*(rr+7)];o+=path([inside,outside],'#789547',3)+circle(...outside,4,'#789547')}}
 for(let i=0;i<8;i++){let target;if(bile&&s.split>.95){const a=i*Math.PI/4;target=[x+Math.cos(a)*(100+s.drops.at(-1).r+12),cy+Math.sin(a)*(100+s.drops.at(-1).r+12)]}else{const a=i*Math.PI/4;target=[x+Math.cos(a)*(60*Math.cbrt(s.remaining)+12),cy+Math.sin(a)*(60*Math.cbrt(s.remaining)+12)]}const a=i/8*Math.PI*2,p=at([[x+Math.cos(a)*183,cy+Math.sin(a)*115],target],ramp(t,.4,.6));o+=enzymeGlyph(...p,`${k}-${i}`,i*45+180)}
 for(let i=0;i<s.digested;i++){const px=x-150+i%4*90,py=598+Math.floor(i/4)*40;o+=`<g data-digested-portion="${k}-${i}">`+path([[px-12,py],[px-6,py-6],[px+2,py+6],[px+10,py]],'#9164a3',4)+circle(px+21,py,5,'#9164a3')+'</g>'}
 o+=txt(x,710,bile&&s.split===1?'After emulsification: surface 2×':s.split>0?'Surface increases as drops separate':'Initial exposed area: 1×',bile&&s.split===1?'乳化後表面積：2 倍':s.split>0?'油滴分散時表面積增加':'最初表面積：1 倍',21);
 return o;}
function bileExperiment(t){const bx=95,by=145,bw=930,bh=610,mid=560,cy=425;let o=txt(560,35,'Bile salts: more fat surface for lipase','膽鹽：讓脂肪酶接觸更多脂肪表面',25);
 o+=`<rect x="${bx}" y="${by}" width="${bw}" height="${bh}" rx="18" fill="#faf7f0" stroke="#b5bda9" stroke-width="3" data-lipase-compare-box="true"/>`;
 o+=`<rect x="${bx+3}" y="${by+3}" width="${mid-bx-6}" height="${bh-6}" fill="#fcf3e8"/>`;
 o+=`<rect x="${mid}" y="${by+3}" width="${bx+bw-mid-3}" height="${bh-6}" fill="#f0f6ee"/>`;
 o+=path([[mid,by+24],[mid,by+bh-24]],'#c9bfae',3);
 o+=txt(mid,165,'Compare','對照',19);
 o+=bileLipasePanel(t,false,315,cy,0)+bileLipasePanel(t,true,805,cy,1);
 o+=txt(560,795,'Emulsification is physical; lipase performs chemical digestion.','乳化屬物理作用；化學消化由脂肪酶進行。',18);return V.wrap(o,'Bile salts, equal fat volume and lipase access');}
function diffusionState(t){return Array.from({length:20},(_,i)=>{const left=i<16,index=left?i:i-16,cross=left?index<8:index<2,start=[left?170+index%4*65:750+index%2*65,285+Math.floor(index/(left?4:2))*70],end=cross?[left?680+index%4*65:230+index%2*65,300+Math.floor(index/(left?4:2))*80]:left?start:[start[0],495],gate=300+(index%4)*70,pre=[left?520:600,gate],post=[left?600:520,gate],q=ramp(t,.02,.98);let p=cross?(q<.35?at([start,pre],q/.35):q<.55?at([pre,post],(q-.35)/.2):at([post,end],(q-.55)/.45)):at([start,end],q);if(!cross)p=[p[0]+Math.sin(t*12+i)*13,p[1]+Math.sin(t*9+i)*12];return {id:i,left,cross,p}})}
function diffusion(t){let o=txt(560,35,'Glucose diffusion: movement in BOTH directions','葡萄糖擴散：粒子向兩個方向移動',25);o+=`<rect x="100" y="185" width="920" height="445" rx="20" fill="#f8f4e9" stroke="#c4b39c"/>`;
 for(const [a,b]of [[185,285],[315,355],[385,425],[455,495],[525,630]])o+=path([[560,a],[560,b]],'#b18b72',18);
 for(const y of [300,370,440,510])o+=path([[544,y-15],[544,y+15]],'#438e76',8)+path([[576,y-15],[576,y+15]],'#438e76',8);
 const a=diffusionState(t),left=a.filter(p=>p.p[0]<550).length,right=a.filter(p=>p.p[0]>570).length;for(const p of a)o+=token(...p.p,'glucose',`data-diffusing-glucose="${p.id}" data-crosses="${p.cross}"`,10);
 o+=txt(310,157,`Left: ${left} glucose`, `左方：${left} 個葡萄糖標記`,22)+txt(810,157,`Right: ${right} glucose`,`右方：${right} 個葡萄糖標記`,22)+txt(560,691,'8 move right; 2 move left → net 6 move right','8 個向右、2 個向左 → 淨移動 6 個向右',21)+txt(560,755,'Glucose needs transport proteins; this facilitated diffusion uses no ATP.','葡萄糖需要運輸蛋白；此促進擴散不消耗 ATP。',18);return V.wrap(o,'Bidirectional facilitated diffusion of glucose');}
function scurvy(t,bad,x,w){const q=bad?ramp(t,.12,.62):0,bleed=bad?ramp(t,.65,1):0;let o=`<g data-clinical-condition="${bad?'affected':'healthy'}" data-phase="${t}" transform="translate(${x} 0)"><rect x="0" y="115" width="${w}" height="665" rx="20" fill="${bad?'#fff2e9':'#f1f7ee'}" stroke="#c0ad97"/>`+txt(w/2,159,bad?'Abnormal':'Normal',bad?'異常':'正常',24)+txt(w/2,219,'Teeth and gum margin','牙齒及齒齦邊緣',21);
 const cx=w/2,margin=430-30*q;
 for(const dx of [-87,87]){const a=bad?Math.sin(t*18)*ramp(t,.9,1)*1.2:0;o+=`<g transform="rotate(${a} ${cx+dx} 430)"><path data-scurvy-tooth="true" d="M${cx+dx-72} 425 Q${cx+dx-88} 330 ${cx+dx-67} 295 Q${cx+dx-40} 270 ${cx+dx-12} 294 Q${cx+dx+10} 275 ${cx+dx+32} 289 Q${cx+dx+84} 272 ${cx+dx+74} 348 L${cx+dx+62} 445Z" fill="#f5f0dd" stroke="#b5aa8c" stroke-width="3"/><path d="M${cx+dx-50} 310 Q${cx+dx-10} 328 ${cx+dx+40} 307" fill="none" stroke="#d7ccae" stroke-width="3"/></g>`}
 // External gingival margin adapted from the existing tooth explorer: roots stay covered.
 o+=`<path data-gum-swelling="${q}" d="M35 450 Q${cx-160} ${margin-12} ${cx-80} ${margin+5} Q${cx-30} ${margin+15} ${cx} ${margin-25} Q${cx+30} ${margin+15} ${cx+80} ${margin+5} Q${cx+160} ${margin-12} ${w-35} 450 V520 Q${cx} 547 35 520Z" fill="${bad&&q>.1?'#b65a71':'#cb8d91'}" stroke="#a86177" stroke-width="3"/>`;
 for(let i=0;i<4;i++)if(bleed>0){const xx=cx-37+i*25,yy=margin-7+Math.abs(i-1.5)*5;o+=circle(xx,yy+bleed*8,(6+i%2*2)*bleed,'#a9233e',`data-gum-bleeding="${i}"`)+path([[xx,yy],[xx+3,yy+bleed*22]],'#a9233e',3*bleed)}
 o+=txt(cx,565,'Gum-tissue close-up: capillary + collagen','齒齦組織放大：微血管及膠原纖維',17)+path([[65,615],[w-65,615]],'#bd7184',24)+path([[65,615],[w-65,615]],'#f2d7de',16);
 for(let j=0;j<3;j++)for(let i=0;i<8;i++){if(bad&&q>.35&&(i+j)%3===0)continue;const xx=65+i*(w-130)/8,yy=[592,642,674][j];o+=path([[xx,yy],[xx+(w-130)/16,yy+4],[xx+(w-130)/8,yy]],'#a98a6a',3)}
 for(let i=0;i<5;i++){const xx=90+i*(w-180)/4,leak=bad&&i<3?bleed:0;o+=circle(xx,615+leak*33,5,'#b94460',`data-gum-capillary-cell="${i}" data-leaked="${leak>0}"`)}
 o+=txt(cx,717,bad?'Weaker support → fragile, bleeding gums':'Supported tissue; blood stays in capillary',bad?'支持組織變弱 → 齒齦脆弱及出血':'組織有支持；血液留在微血管內',18);return o+'</g>';}
window.learningSceneSVG=(mode,s)=>{const t=M.clamp(s.phase||0);if(mode==='villi'&&s.adaptation==='overview')return overview(t);if(mode==='application'&&s.application==='experiments'&&(!s.experiment||s.experiment==='lipase'))return bileExperiment(t);if(mode==='application'&&s.application==='processes'&&(!s.transportProcess||s.transportProcess==='diffusion'))return diffusion(t);if(mode==='application'&&s.application==='scurvy')return V.wrap(s.compareBoth?scurvy(t,false,25,520)+scurvy(t,true,575,520):scurvy(t,s.diseaseComparison!=='healthy',230,660),'Scurvy: tooth and gum model');return oldRender(mode,s)};
const teaching=(where,labels,steps,breaks=[0,.25,.5,.75,1])=>({where,labels,steps,breaks});
window.processTeaching=(mode,s)=>{if(mode==='villi'&&s.adaptation==='overview')return teaching('Whole villus → enlarged epithelial cell 絨毛 → 放大上皮細胞',['See the structures 看結構','Microvilli 微絨毛','Mitochondria 線粒體','Short route 短路徑'],['The left villus has one epithelial cell layer; the dashed lines identify an enlarged cell on the right. 左邊絨毛表面只有一層細胞；虛線連到右邊的放大細胞。','The finger-like brush border is part of the cell membrane. More exposed membrane provides more transport sites. 刷狀緣是細胞膜的指狀突起，增加表面及運輸位置。','Many mitochondria release energy as ATP. ATP powers the sodium pump, helping maintain the gradient used for glucose uptake. 大量線粒體供 ATP 驅動鈉泵，維持葡萄糖吸收所需梯度。','Glucose crosses one epithelial cell then enters capillary blood. The one-cell layer keeps this route short. 葡萄糖穿過一個上皮細胞後進微血管，單層令路徑短。']);
 if(mode==='application'&&s.application==='experiments'&&(!s.experiment||s.experiment==='lipase'))return teaching('Fat in intestinal fluid 腸液中的脂肪',['Same fat amount 相同脂肪量','Emulsify 乳化','Lipase binds 酶接觸','Digestion products 消化產物'],['One comparison box: lipase alone on the left, lipase with bile on the right. Both begin with the same fat volume. Amber circles are fat, green heads/tails are bile salts, blue notched shapes are lipase. 同一個對照框：左邊只有脂肪酶，右邊有脂肪酶及膽鹽；兩邊脂肪量相同。橙色圓為脂肪、綠色頭尾為膽鹽、藍色缺口形為脂肪酶。','Bile salts help disperse one large droplet into smaller droplets. Eight spheres of half the radius have the same total volume and twice the total surface area. This is not diffusion or chemical digestion. 膽鹽協助大油滴分散；八個半徑一半的小球體積總和相同、表面積總和為兩倍。這不是擴散或化學消化。','Lipase reaches the exposed fat/water boundary. Both sides have the same eight enzyme markers; enzymes remain present. 脂肪酶接觸油水界面，兩邊同為八個酶標記，酶不被消耗。','Purple chains and dots represent fat digestion products, including fatty-acid and glycerol components in the course model. Faster fatty-acid formation gives a faster pH fall. The counts are an illustration, not experimental data. 紫色鏈及圓代表課程模型中的脂肪酸、甘油等消化產物；脂肪酸形成較快，pH 下降較快。數量只作示意。'],[0,.1,.4,.53,1]);
 if(mode==='application'&&s.application==='processes'&&(!s.transportProcess||s.transportProcess==='diffusion'))return teaching('Glucose crosses transport proteins 葡萄糖經運輸蛋白',['Unequal concentrations 濃度不同','Both directions 雙向移動','Net transfer 淨移動','Equal concentrations 濃度相同'],['Every gold hexagon is glucose: initially 16 on the left, 4 on the right. Each side has the same volume. 金色六角形全是葡萄糖，起初左16右4，兩邊體積相同。','Track the same 20 glucose markers. Eight cross rightwards and two cross leftwards through membrane transport proteins. 同一批20個標記中，8個經膜運輸蛋白向右、2個向左。','The net transfer is six to the right, from higher to lower glucose concentration. No ATP is used in facilitated diffusion. 淨移動6個向右，由高濃度到低濃度；促進擴散不需 ATP。','The result is 10 on each side. Molecular movement continues at equilibrium; this timeline holds its endpoint for comparison. 最後兩邊各10個；平衡時分子仍運動，進度終點只為保留結果。']);
 if(mode==='application'&&s.application==='scurvy')return teaching('Vitamin C → collagen support → gums 維生素C → 膠原支持 → 齒齦',['Teeth + gums 牙齒齒齦','Weaker support 支持變弱','Swollen gum 齒齦紅腫','Bleeding 出血'],['This uses the external two-tooth gum view from the tooth model; roots stay covered. The lower strip magnifies gum tissue. 以牙齒模型的兩牙及外部齒齦視圖作比較；牙根仍被覆蓋，下方放大齒齦組織。','Long-term vitamin C deficiency impairs collagen formation. Broken brown fibres show weaker connective support, not damage to enamel. 長期缺乏維生素C影響膠原形成；棕色纖維斷續表示支持變弱，並非琺瑯質損壞。','Affected gums become red and swollen. The healthy side stays snug against the tooth surface. 異常齒齦紅腫隆起，正常側仍貼合牙面。','Fragile tissue and capillaries allow bleeding at the gum margin. Advanced deficiency can loosen teeth. Progression is compressed; vitamin C is a helper, not fibre material. 脆弱組織及微血管使齒齦邊緣出血，嚴重時牙齒可鬆動。此為壓縮進程；維生素C並非纖維原料。']);return oldTeaching(mode,s)};
P.spec=(mode,s)=>{const key=(shape,color,en,zh)=>({shape,color,en,zh});if(mode==='villi'&&s.adaptation==='overview')return {box:[0,145,1120,620],items:[key('hex','#c68a16','Glucose','葡萄糖'),key('dot','#cba62e','ATP energy carrier','ATP 能量載體'),key('gate','#438e76','Transport protein / pump','運輸蛋白／泵')]};if(mode==='application'&&s.application==='experiments'&&(!s.experiment||s.experiment==='lipase'))return {box:[0,125,1120,650],items:[key('dot','#e5b56b','Fat droplet','脂肪滴'),key('line','#789547','Bile salts','膽鹽'),key('enzyme','#397fa8','Lipase enzyme','脂肪酶'),key('chain','#9164a3','Digestion products','消化產物')],note:'Droplets represent spheres; emulsification preserves total fat volume. 油滴表示球體；乳化時脂肪總體積不變。'};if(mode==='application'&&s.application==='processes'&&(!s.transportProcess||s.transportProcess==='diffusion'))return {box:[0,120,1120,650],items:[key('hex','#c68a16','Glucose','葡萄糖'),key('gate','#438e76','Transport protein','運輸蛋白')],note:'Gold hexagons are glucose, not energy or blood cells. 金色六角形為葡萄糖，並非能量或血球。'};if(mode==='application'&&s.application==='scurvy')return {box:[0,130,1120,625],items:[key('line','#a98a6a','Collagen support','膠原支持'),key('dot','#b94460','Blood cells / bleeding','血球／出血')],note:'External gum view + separate tissue close-up. 外部齒齦視圖及獨立組織放大圖。'};return oldSpec(mode,s)};
// Resolve spec at call time so every new scene receives its own native legend.
window.presentLearningScene=(mode,s,svg)=>{const cfg=P.spec(mode,s);return cfg?P.compact(svg,cfg)+P.legend(cfg.items,cfg.note):svg};
window.ClarityRevision={overview,bileState,bileExperiment,diffusionState,diffusion,scurvy};
const tab=window.APPLICATION_TABS.find(a=>a.id==='scurvy');tab.content+='<p>Swollen, bleeding gums and loosened teeth can result from tissue and capillary fragility in scurvy. This is different from tooth decay.<br>壞血病令組織及微血管脆弱，可造成齒齦紅腫、出血及牙齒鬆動；這與蛀牙不同。</p>';
})();
